import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { tasksApi } from '@/api/tasks.api'
import type { TaskCreate, TaskResponse, TaskUpdate } from '@/types/task.types'

export const useTasksStore = defineStore('tasks', () => {
  const tasks = ref<TaskResponse[]>([])
  const loading = ref(false)

  const tasksByQuadrant = computed(() => ({
    q1: tasks.value.filter(t => t.quadrant === 'urgent_important'),
    q2: tasks.value.filter(t => t.quadrant === 'not_urgent_important'),
    q3: tasks.value.filter(t => t.quadrant === 'urgent_not_important'),
    q4: tasks.value.filter(t => t.quadrant === 'not_urgent_not_important')
  }))

  async function fetchTasks() {
    loading.value = true
    try {
      tasks.value = await tasksApi.getTasks()
    } finally {
      loading.value = false
    }
  }

  async function createTask(data: TaskCreate) {
    const task = await tasksApi.createTask(data)
    tasks.value.unshift(task)
    return task
  }

  async function updateTask(id: string, data: TaskUpdate) {
    const task = await tasksApi.updateTask(id, data)
    const index = tasks.value.findIndex(t => t.id === id)
    if (index !== -1) {
      tasks.value[index] = task
    }
    return task
  }

  async function deleteTask(id: string) {
    await tasksApi.deleteTask(id)
    tasks.value = tasks.value.filter(t => t.id !== id)
  }

  async function completeTask(id: string, actualMinutes?: number) {
    const result = await tasksApi.completeTask(id, actualMinutes)
    const index = tasks.value.findIndex(t => t.id === id)
    if (index !== -1) {
      tasks.value[index] = result.task
    }
    return result
  }

  return {
    tasks,
    loading,
    tasksByQuadrant,
    fetchTasks,
    createTask,
    updateTask,
    deleteTask,
    completeTask
  }
})

